#!/usr/bin/env python3
"""Minimal yaml-subset validator mirroring tools/check_site.py (no PyYAML).

Only the front-matter subset used by this site is supported:
scalar key: value, nested maps (2-level), and `summary: |` block scalars.
"""
import pathlib
import re
import sys

MAX_WORDS = 200
REQUIRED = {
    "project": ["title", "updated", "tldr", "summary"],
    "series": ["title", "series", "order", "status", "updated", "tldr", "summary"],
    "experiment": ["title", "series", "status", "date", "updated", "tldr", "summary"],
}

root = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else "site")

def parse_frontmatter(text):
    m = re.match(r"^---\n(.*?)\n---\n", text, re.S)
    if not m:
        return None
    lines = m.group(1).splitlines()
    out = {}
    i = 0
    while i < len(lines):
        line = lines[i]
        if not line or line.startswith("#"):
            i += 1
            continue
        # block scalar (summary: | or >)
        sm = re.match(r'^(\w+):\s*\|', line)
        if sm:
            key = sm.group(1)
            val_lines = []
            j = i + 1
            indent = None
            while j < len(lines) and (lines[j] == "" or lines[j].startswith(" ")):
                if lines[j] == "":
                    val_lines.append("")
                else:
                    if indent is None:
                        indent = len(lines[j]) - len(lines[j].lstrip(" "))
                    stripped = lines[j].lstrip(" ") if len(lines[j].lstrip(" ")) < indent else ""
                    val_lines.append(stripped)
                j += 1
            out[key] = "\n".join(val_lines)
            i = j
            continue
        # plain key: value
        sm = re.match(r'^(\w+):\s*(.*)$', line)
        if sm and not line.startswith("  "):
            key = sm.group(1)
            val = sm.group(2).strip()
            if val:
                out[key] = val
            else:
                # nested map
                nested = {}
                j = i + 1
                while j < len(lines):
                    nm = re.match(r'^  ([\w-]+):\s*(.*)$', lines[j])
                    if not nm or not lines[j].startswith(" "):
                        break
                    nested[nm.group(1)] = nm.group(2).strip()
                    j += 1
                out[key] = nested
            i += 1
            continue
        i += 1
    return out

pages = []
for f in sorted(root.rglob("*.md")):
    if any(part.startswith("_") for part in f.relative_to(root).parts) or f.name == "AUTHORING.md":
        continue
    fm = parse_frontmatter(f.read_text())
    if fm is None:
        continue
    if "layer" in fm:
        pages.append((f.relative_to(root), fm))

errors = []
for f, fm in pages:
    layer = fm["layer"]
    if layer not in REQUIRED:
        errors.append(f"{f}: unknown layer {layer!r}")
        continue
    for k in REQUIRED[layer]:
        if fm.get(k) in (None, ""):
            errors.append(f"{f}: missing {k}")
    words = len(re.findall(r"\S+", str(fm.get("summary", ""))))
    if words > MAX_WORDS:
        errors.append(f"{f}: summary is {words} words (max {MAX_WORDS})")

projects = [p for p in pages if p[1]["layer"] == "project"]
series = {fm.get("series"): (f, fm) for f, fm in pages if fm["layer"] == "series"}
experiments = [p for p in pages if p[1]["layer"] == "experiment"]
if len(projects) != 1:
    errors.append(f"expected exactly one project page, found {len(projects)}")

def stale(parent, child):
    (pf, pfm), (cf, cfm) = parent, child
    if pfm.get("updated") and cfm.get("updated") and pfm["updated"] < cfm["updated"]:
        errors.append(f"{pf}: updated {pfm['updated']} older than child {cf} ({cfm['updated']})")

for e in experiments:
    s = series.get(e[1].get("series"))
    if s is None:
        errors.append(f"{e[0]}: series {e[1].get('series')!r} has no series page")
    else:
        stale(s, e)
for s in series.values():
    for p in projects:
        stale(p, s)

for err in errors:
    print("ERROR", err)
print(f"{len(pages)} pages checked, {len(errors)} errors")
sys.exit(1 if errors else 0)
